corporate_design.toad_component_blueprint:
canvas {
  size: 880px 560px;
  fill: #F7FEE7;
  font-family: "Inter, sans-serif";
}

>green = #65A30D;
>pink = #BE185D;

rect #bowlCard {
  at: center of canvas;
  size: 780px 460px;
  fill: #FFFFFF;
  radius: 16px;
}

text #bowlHeader {
  at: top left of #bowlCard offset 36px 36px;
  content: "URBANLEAF // FRESH CRUNCH BOWLS";
  font-size: 13px;
  font-weight: 700;
  color: >green;
}

text #bowlTitle {
  at: below #bowlHeader offset 14px;
  content: "Wild Salmon & Sesame Avocado Bowl";
  font-size: 30px;
  font-weight: 700;
  color: #1E293B;
}
